import{_ as i,C as o,o as s,c as d,E as n,a2 as a}from"./chunks/framework.Cm6XCzck.js";const S=JSON.parse('{"title":"CodeFlowMu 工程化实录（二）：Session 身份不能靠自报——如何建立可验证的执行证据边界","description":"","frontmatter":{"title":"CodeFlowMu 工程化实录（二）：Session 身份不能靠自报——如何建立可验证的执行证据边界","date":"2026-08-28","updated":"2026-08-31","column":"digital-employee","category":"daily","article_type":"engineering-analysis","edition":"research-center","research_question":"当技能调用携带 session_id 时，Runtime 怎样区分调用方声明、权威会话事实与可审计的执行证据？","summary":"CodeFlowMu 的历史技能日志暴露了一个比缺字段更深的工程问题：session_id 即使被写入，也不能仅凭调用方自报就成为可信执行证据。V2.1.2 将普通技能调用交由 Runtime 对照 SessionStore 核验 task、thread、session、agent 与 caller，并用 verified、sessionless/not_applicable、invalid_claim 明确区分可信绑定、合法无会话与错误声明。","sources":"/zh/research/evidence/2026-08-28-skill-session-evidence","project_relevance":"substantive-relationship","item_id":"RBE-20260828-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-28-skill-session-evidence-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-08-28-skill-session-evidence.md","filePath":"zh/digital-employee/2026-08-28-skill-session-evidence.md","lastUpdated":1788144592000}'),l={name:"zh/digital-employee/2026-08-28-skill-session-evidence.md"};function r(c,e,p,h,u,g){const t=o("ArticleCover");return s(),d("div",null,[n(t,{image:"/assets/covers/daily-2026-08-28-skill-session-evidence-cover.png",kicker:"CodeFlowMu 工程化实录 · 02",title:"Session 身份不能靠自报——如何建立可验证的执行证据边界",summary:"日志里出现一个 session_id，只能证明有人写了这个字符串。要把它升级为执行证据，Runtime 必须回到自己的权威会话事实。",version:"RBE-20260828-03",status:"工程分析 · 2026-08-31 修订"}),e[0]||(e[0]=a('<h1 id="codeflowmu-工程化实录-二-session-身份不能靠自报——如何建立可验证的执行证据边界" tabindex="-1">CodeFlowMu 工程化实录（二）：Session 身份不能靠自报——如何建立可验证的执行证据边界 <a class="header-anchor" href="#codeflowmu-工程化实录-二-session-身份不能靠自报——如何建立可验证的执行证据边界" aria-label="Permalink to &quot;CodeFlowMu 工程化实录（二）：Session 身份不能靠自报——如何建立可验证的执行证据边界&quot;">​</a></h1><p>一条技能调用日志可以写得很完整：任务编号、技能名称、<code>outcome=ok</code>、调用时间，甚至还有完整性摘要。</p><p>但只要再问一句——<strong>这次调用到底属于哪一个真实 Agent Session？</strong>——很多看似完整的日志就会暴露出证据等级的问题。</p><h2 id="codeflowmu-是什么-为什么-session-会成为核心证据" tabindex="-1">CodeFlowMu 是什么，为什么 Session 会成为核心证据 <a class="header-anchor" href="#codeflowmu-是什么-为什么-session-会成为核心证据" aria-label="Permalink to &quot;CodeFlowMu 是什么，为什么 Session 会成为核心证据&quot;">​</a></h2><p>CodeFlowMu 是一个<strong>本地优先的多 Agent 协作与数字员工运行体</strong>。它让不同职责的 Agent 在受控工作空间里持续执行任务，Runtime 则负责维护任务对象、线程、Session、工具调用、Activity、恢复状态和审计证据。</p><p>在这种系统里，一张 TASK 往往不只对应一次模型调用。它可能经历首次执行、崩溃恢复、返工、再次验证，甚至由不同 Agent 在不同 Session 中接续工作。于是仅有 <code>task_id</code> 已经不够回答“某个动作到底发生在哪一次真实执行里”。</p><p>这也是 Session 证据的重要性：它不是聊天界面的临时上下文标签，而是 Runtime 区分执行轮次、恢复边界和审计归属的身份事实。</p><p>最直接的做法似乎很简单：让调用方多传一个 <code>session_id</code>，原样写进日志。</p><p>这仍然不够。</p><p>因为一个非空 <code>session_id</code> 首先只是<strong>调用方声明</strong>。它可能来自正确会话，也可能已经结束、属于另一个任务、另一个 Agent，甚至根本没有在 Runtime 中注册。如果系统因为“字符串存在”就把它标记为可信绑定，审计记录反而会比真实事实更强。</p><p>CodeFlowMu 在把数字员工运行链路工程化时遇到的正是这个问题。历史版本首先暴露了 Session 传播缺口；进一步设计时，我们又确认：真正要补的不是一个字段，而是一条<strong>执行身份的权威核验边界</strong>。</p><p>V2.1.2 最终把这条边界落在 Runtime：技能调用携带的会话身份不再直接成为事实，而是先与 SessionStore 中的权威记录核对，再形成 <code>verified</code>、<code>sessionless/not_applicable</code> 或 <code>invalid_claim</code> 等明确审计语义。</p><p>完整历史剖面、版本边界与公开证据见：<a href="/joinwell52/zh/research/evidence/2026-08-28-skill-session-evidence">RBE-20260828-03 证据页</a>。</p><h2 id="外部研究起点-配置存在-不等于进入了这次会话" tabindex="-1">外部研究起点：配置存在，不等于进入了这次会话 <a class="header-anchor" href="#外部研究起点-配置存在-不等于进入了这次会话" aria-label="Permalink to &quot;外部研究起点：配置存在，不等于进入了这次会话&quot;">​</a></h2><p>这条研究链的外部对照来自 <a href="https://github.com/OpenHands/OpenHands/pull/16971" target="_blank" rel="noreferrer">OpenHands PR #16971</a>，题为 <code>fix(api): auto-load workspace hooks on conversation start</code>。</p><p>在 2026-08-28 的原研究记录里，它仍是开放提案，因此本文保留当时状态，不把它改写成已经正式发布的对方能力。</p><p>这个提案讨论的是：工作区里已经存在 <code>.openhands/hooks.json</code>，但 Agent Canvas 启动 conversation 时没有自动把这份配置带入当前会话。它提出在 conversation admission 时加载 hook 配置，并通过 session 状态里的 <code>hook_config</code> 和实际 <code>HookExecutionEvent</code> 检查是否生效。</p><p>它给我们的启发不是“CodeFlowMu 也该照着做 hook 自动加载”，而是一条更通用的证据原则：</p><p><strong>资源存在、资源进入会话、资源被实际调用、调用产生正确结果，是四件不同的事。</strong></p><p>OpenHands 的问题更靠前：<code>配置存在 → 是否进入当前 conversation</code>。</p><p>CodeFlowMu 这次的问题更靠后：<code>已经观察到调用 → 这条调用记录到底属于哪个权威 Session</code>。</p><p>因此两者是相邻问题，不是同一个 Bug，也不是同一份实现。</p><h2 id="历史断点-runtime-知道-session-持久证据却丢了它" tabindex="-1">历史断点：Runtime 知道 Session，持久证据却丢了它 <a class="header-anchor" href="#历史断点-runtime-知道-session-持久证据却丢了它" aria-label="Permalink to &quot;历史断点：Runtime 知道 Session，持久证据却丢了它&quot;">​</a></h2><p>在 CodeFlowMu V2.0.4 固定提交 <code>2ba1ad9b</code> 的普通 Playbook 读取路径中，运行时实际上已经接收 agent、session、task 和 thread。它能识别 SDK 工具调用是否读取技能文件，也会使用 <code>session_id + skill_id</code> 做短期去重。</p><p>但在最终写入调用 journal 的 <code>recordSkillInvocation()</code> 路径里，task 和 thread 被继续传递，session 却没有进入持久记录。</p><p>传播断点因此非常明确：</p><p><code>运行时知道 Session → 用 Session 做短期处理 → 持久证据丢失 Session 归属</code></p><p>旧日志把这个断点留下得很清楚。我们检查截至 2026-08-12 的 59 条历史技能记录：</p><table tabindex="0"><thead><tr><th>关联字段</th><th style="text-align:right;">存在</th><th style="text-align:right;">缺失</th><th style="text-align:right;">缺失率</th></tr></thead><tbody><tr><td><code>task_id</code></td><td style="text-align:right;">49</td><td style="text-align:right;">10</td><td style="text-align:right;">16.9%</td></tr><tr><td><code>session_id</code></td><td style="text-align:right;">0</td><td style="text-align:right;">59</td><td style="text-align:right;">100.0%</td></tr><tr><td><code>thread_key</code></td><td style="text-align:right;">42</td><td style="text-align:right;">17</td><td style="text-align:right;">28.8%</td></tr><tr><td><code>agent_id</code></td><td style="text-align:right;">15</td><td style="text-align:right;">44</td><td style="text-align:right;">74.6%</td></tr><tr><td><code>integrity</code></td><td style="text-align:right;">59</td><td style="text-align:right;">0</td><td style="text-align:right;">0%</td></tr></tbody></table><p>这 59 条记录只是一批冻结历史样本，不代表所有版本、所有技能入口或生产频率。它们能说明的是：<strong>这批持久记录具有完整性字段，却无法仅靠自身还原真实会话归属。</strong></p><p>这里还有一个重要区别：<code>integrity</code> 存在不代表 Session 身份真实。</p><p>一条记录可以“从写入后没有被篡改”，但它写进去的身份本身仍可能错误。完整性只能证明记录保持原样，不能证明原始声明就是事实。</p><h2 id="同一系统里的反例-目标不是-给所有技能补一个-session-字段" tabindex="-1">同一系统里的反例：目标不是“给所有技能补一个 session 字段” <a class="header-anchor" href="#同一系统里的反例-目标不是-给所有技能补一个-session-字段" aria-label="Permalink to &quot;同一系统里的反例：目标不是“给所有技能补一个 session 字段”&quot;">​</a></h2><p>CodeFlowMu 并不是所有技能证据都处于同一强度。</p><p>同一固定版本里的 <code>pm.record_planning_skill_evidence</code> 是一个更强的规划证据入口：它会把请求与 Runtime 已掌握的 task、session、caller 和 thread 等上下文核对，再保存规划技能证据。</p><table tabindex="0"><thead><tr><th>记录类型</th><th>已能证明</th><th>仍不能证明</th></tr></thead><tbody><tr><td>普通 Skill / Playbook 调用记录</td><td>观察到某技能被读取，带部分任务上下文</td><td>无法还原可信 Session 归属</td></tr><tr><td>正式规划技能证据</td><td>task/thread/session/caller 等经过 Runtime authority 核对</td><td>不能因此证明代码、测试或最终业务结果正确</td></tr></tbody></table><p>所以工程目标不能写成“Skill Framework 缺 session”。真正的目标是：</p><p><strong>让普通 invocation evidence 也拥有明确的身份来源等级，而不是把客户端自报字段直接升级为 Runtime 事实。</strong></p><p>这一步是从日志工程走向证据工程的分界。</p><h2 id="为什么把-session-id-原样写进去反而可能制造假证据" tabindex="-1">为什么把 <code>session_id</code> 原样写进去反而可能制造假证据 <a class="header-anchor" href="#为什么把-session-id-原样写进去反而可能制造假证据" aria-label="Permalink to &quot;为什么把 `session_id` 原样写进去反而可能制造假证据&quot;">​</a></h2><p>假设调用请求里出现：</p><p><code>session_id = session-042</code></p><p>系统至少还不知道：</p><ol><li><code>session-042</code> 是否真实存在于当前 Runtime 的 SessionStore；</li><li>它是否属于当前 <code>task_id</code>；</li><li>它是否属于当前 <code>thread_key</code>；</li><li>它记录的 Agent 是否与当前调用 Agent 一致；</li><li>当前 caller 是否有资格把这次调用归属于该 Session，以及 Session 当前状态是否仍可接受。</li></ol><p>如果这些都不核对，只因为字符串长得像 Session ID 就持久化为“已绑定”，以后 EVAL、恢复器、审计面板或 ADMIN 看到的就不是弱证据，而是<strong>被系统包装过的错误强证据</strong>。</p><p>这种错误比字段为空更危险。字段为空至少明确告诉后续消费者“这里不知道”；未经核验却显示为可信的 Session，则会让系统错误地回答“我知道这次是谁、在哪一轮执行的”。</p><p>因此 V2.1.2 的原则是：</p><blockquote><p><strong>声明可以保存，但只有 Runtime 自己能够核验的声明，才能升级为执行身份事实。</strong></p></blockquote><h2 id="v2-1-2-session-身份回到-runtime-authority" tabindex="-1">V2.1.2：Session 身份回到 Runtime authority <a class="header-anchor" href="#v2-1-2-session-身份回到-runtime-authority" aria-label="Permalink to &quot;V2.1.2：Session 身份回到 Runtime authority&quot;">​</a></h2><p>V2.1.2 不再把调用方提交的 <code>session_id</code> 直接视为执行证据，而是由 Runtime 读取 SessionStore，并围绕实际可用上下文核对：</p><ul><li><code>task_id</code>；</li><li><code>thread_key</code>；</li><li><code>session_id</code>；</li><li>agent；</li><li>caller；</li><li>Session 是否存在、状态是否处于可接受范围。</li></ul><p>核验后，调用 journal 不再只有“有 Session / 没 Session”两个模糊状态，而是形成明确的证据语义：</p><table tabindex="0"><thead><tr><th>情况</th><th>持久化语义</th><th>审计含义</th></tr></thead><tbody><tr><td>SessionStore 记录存在，身份和已有上下文一致</td><td><code>session_binding=verified</code></td><td>这次调用的会话归属得到 Runtime 权威事实支持</td></tr><tr><td>该调用按设计合法不需要 Session，并有 Runtime 原因</td><td><code>sessionless/not_applicable</code></td><td>无 Session 是合法语义，不是漏写</td></tr><tr><td>Session 未注册、状态不接受、Agent/caller/task/thread 等出现不一致</td><td><code>session_binding=invalid_claim</code></td><td>保留为负面审计事实，不能升级为已验证执行证据</td></tr></tbody></table><p>这三个状态把过去混在一起的三种情况拆开了：</p><p><strong>真的绑定成功、设计上不需要绑定、有人声称绑定但事实不支持。</strong></p><p>尤其是 <code>invalid_claim</code>，它不能被悄悄丢弃。</p><p>如果系统发现一个错误 Session 就直接改成 <code>session_id=null</code>，以后审计只能看到“没有 Session”，却看不到“曾经有人声称这是某个 Session，但核验失败”。V2.1.2 因此把错误声明留下来，作为负面证据。</p><p>负面证据同样是证据。</p><h2 id="invalid-claim-为什么不能自动-修好" tabindex="-1"><code>invalid_claim</code> 为什么不能自动“修好” <a class="header-anchor" href="#invalid-claim-为什么不能自动-修好" aria-label="Permalink to &quot;`invalid_claim` 为什么不能自动“修好”&quot;">​</a></h2><p>Agent 系统里很容易出现一种看似友好的自动修复冲动：调用方给错了 Session，如果 Runtime 能猜到“它可能想写另一个 Session”，是否可以自动替换？</p><p>对执行证据来说，这种自动修复风险很高。</p><p>因为一旦系统主动把未经证明的身份替换成“最像的那个”，它就从事实记录器变成了身份推理器。后续所有审计链都会失去“原始声明是什么、权威事实是什么、两者是否一致”的区别。</p><p>更稳健的处理是：</p><p><code>claim → authority verification → evidence state</code></p><p>而不是：</p><p><code>claim → best guess → pretend verified</code></p><p>未来如果业务层需要恢复、重新绑定或人工纠正，那应该产生新的、独立可追踪的治理动作，而不是修改历史调用证据的含义。</p><h2 id="task、thread、session、agent、caller-不能互相替代" tabindex="-1">task、thread、session、agent、caller 不能互相替代 <a class="header-anchor" href="#task、thread、session、agent、caller-不能互相替代" aria-label="Permalink to &quot;task、thread、session、agent、caller 不能互相替代&quot;">​</a></h2><p>这些身份键回答的是不同问题：</p><table tabindex="0"><thead><tr><th>身份键</th><th>回答的问题</th></tr></thead><tbody><tr><td><code>task_id</code></td><td>这次执行服务哪个业务任务</td></tr><tr><td><code>thread_key</code></td><td>它位于哪条业务协作或因果链</td></tr><tr><td><code>session_id</code></td><td>它属于哪一次具体运行会话</td></tr><tr><td>agent</td><td>哪个执行角色 / Agent 进行了动作</td></tr><tr><td>caller</td><td>谁发起了这次调用</td></tr></tbody></table><p>一个任务完全可能经历首次执行、崩溃恢复、返工和再次验证等多个 Session。同一 thread 也可能跨越多个角色与任务阶段。</p><p>因此 <code>task_id</code> 不能证明 Session，<code>thread_key</code> 也不能证明 Session；一个自报的 Session 更不能反过来覆盖 task/thread/agent/caller 的不一致。</p><p>V2.1.2 的价值，就是把这些身份维度放回同一个 Runtime authority 边界里核对。</p><h2 id="身份真实性与记录完整性-是两套不同证明" tabindex="-1">身份真实性与记录完整性，是两套不同证明 <a class="header-anchor" href="#身份真实性与记录完整性-是两套不同证明" aria-label="Permalink to &quot;身份真实性与记录完整性，是两套不同证明&quot;">​</a></h2><p>调用 journal 原本就有完整性机制，这次 Session 工程化并没有取代它。</p><ul><li><strong>SessionStore 核验</strong>回答：这条身份声明是否与 Runtime 权威会话事实一致？</li><li><strong>journal 完整性验证</strong>回答：这条已经持久化的记录是否保持可验证完整性？</li></ul><p>一条错误 Session claim 即使拥有合法完整性摘要，仍然只是“完整保存了一条错误声明”。反过来，一条已经 <code>verified</code> 的身份记录如果后来被篡改，也仍需要完整性机制发现。</p><p>这两条证据不能互相代替。</p><p>这也是证据系统与普通日志系统的重要区别：<strong>不是字段越多，证据就越强；必须知道每个字段的 authority 从哪里来。</strong></p><h2 id="独立-qa-验证的是一条真实-sessionstore-绑定链" tabindex="-1">独立 QA：验证的是一条真实 SessionStore 绑定链 <a class="header-anchor" href="#独立-qa-验证的是一条真实-sessionstore-绑定链" aria-label="Permalink to &quot;独立 QA：验证的是一条真实 SessionStore 绑定链&quot;">​</a></h2><p>实现完成后，独立 QA 没有只检查“journal 多了一个 Session 字段”。</p><p>C1 场景先创建真实 SessionStore 记录，再通过普通技能读取入口产生 invocation，随后读取持久 journal，并核对身份和完整性。</p><table tabindex="0"><thead><tr><th>检查项</th><th>结果</th></tr></thead><tbody><tr><td>SessionStore 中存在对应会话</td><td>找到</td></tr><tr><td>本次持久 journal 记录数</td><td>1</td></tr><tr><td>task / thread / session</td><td>3/3 与输入预期一致</td></tr><tr><td>agent / caller</td><td>符合预期</td></tr><tr><td><code>session_binding</code></td><td><code>verified</code></td></tr><tr><td><code>binding_reason</code></td><td><code>runtime_session_store_match</code></td></tr><tr><td><code>evidence_source</code></td><td><code>sdk_tool_call</code></td></tr><tr><td>完整性验证</td><td>通过</td></tr></tbody></table><p>这里同样要保留证据边界。C1 证明的是一个真实、合法 Session 的完整正向绑定链。伪造或未注册 Session、合法 sessionless、跨会话区分和同会话去重等失败/边界分支由定向测试覆盖，不能拿一次 C1 代替所有失败路径的独立 QA。</p><p>历史 59 条缺少 Session 的旧记录也不会因为新版本发布就被自动升级成 <code>verified</code>。没有可靠来源可以恢复的历史身份继续保持未知；不猜测回填，本身就是证据纪律的一部分。</p><h2 id="verified-证明执行归属-不证明工作结果正确" tabindex="-1"><code>verified</code> 证明执行归属，不证明工作结果正确 <a class="header-anchor" href="#verified-证明执行归属-不证明工作结果正确" aria-label="Permalink to &quot;`verified` 证明执行归属，不证明工作结果正确&quot;">​</a></h2><p>假设一条 journal 已经显示正确 task、正确 thread、正确 Session、正确 Agent/caller，并且 <code>session_binding=verified</code>、<code>outcome=ok</code>。</p><p>它能证明的是：<strong>Runtime 有证据支持“这个身份组合下发生了这次技能调用，并且调用本身按接口语义完成”。</strong></p><p>它仍然不能证明：</p><ul><li>技能给出的建议正确；</li><li>Agent 完整遵循了技能；</li><li>代码改动正确；</li><li>测试覆盖充分；</li><li>REPORT 结论成立；</li><li>QA 应该 PASS；</li><li>PM 或 ADMIN 应该批准。</li></ul><p>因此更完整的证据层次仍然是：</p><p><code>available → recommended/bound → invoked → identity_verified → result_verified</code></p><p>最后一层必须由代码差异、工具输出、运行工件、测试、REPORT、REVIEW、EVAL 以及 QA/PM 等治理证据继续完成。</p><p>V2.1.2 补的是<strong>调用归属真实性</strong>，不是给 Runtime 增加业务裁判权。</p><h2 id="对数字员工运行体意味着什么" tabindex="-1">对数字员工运行体意味着什么 <a class="header-anchor" href="#对数字员工运行体意味着什么" aria-label="Permalink to &quot;对数字员工运行体意味着什么&quot;">​</a></h2><p>Session 证据看起来只是日志层的小字段，但对长时间运行的数字员工系统，它实际决定了很多后续能力能否可信建立：</p><ul><li>崩溃恢复时，系统能否判断某条调用属于旧 Session 还是新恢复 Session；</li><li>EVAL 复盘时，能否把某项行为准确归到具体执行轮次；</li><li>多 Agent 协作时，能否区分同一任务上不同 Agent、不同 Session 的行为；</li><li>ADMIN 查看证据时，系统是否会把调用方自报身份错误包装成“Runtime 已验证”；</li><li>后续自动诊断或监测是否能够基于可信执行身份，而不是模糊时间线猜测。</li></ul><p>如果 Session 只是可选字符串，这些能力越自动化，错误归属的后果反而越大。</p><p>所以 CodeFlowMu 这次不是单纯“增强日志字段”，而是在数字员工运行体里明确了一条基础原则：</p><p><strong>执行身份属于 Runtime authority，不属于调用者自我声明。</strong></p><h2 id="从工程补丁到正式版本" tabindex="-1">从工程补丁到正式版本 <a class="header-anchor" href="#从工程补丁到正式版本" aria-label="Permalink to &quot;从工程补丁到正式版本&quot;">​</a></h2><p>V2.1.2 于 2026-08-30 完成私有母版 Runtime/Shell 发布。Session 身份核验与任务幂等、Activity 安全投影一起构成本次 Runtime 边界安全补丁。</p><p>公开文章不直接链接私有 CodeFlowMu 仓库；对外可核查的版本事实、脱敏 C1 结果、兼容性与残余风险统一见本文的<a href="/joinwell52/zh/research/evidence/2026-08-28-skill-session-evidence">公开证据页</a>。</p><p>最终发布验证记录为：</p><ul><li>Runtime：<strong>1842 pass / 0 fail / 1 skip</strong>；</li><li>Shell：<strong>1037 pass / 0 fail / 0 skip</strong>；</li><li>V2.1.1 与 V2.1.2 同协议关键场景各连续 10 轮：Runtime <strong>1630/1630</strong>、Shell <strong>550/550</strong>；</li><li>typecheck、Shell build、安装器契约、规则与版本一致性全部通过。</li></ul><p>这些是整个 V2.1.2 发布集合的验证结果，不是“Session 证据可信率”，也不能由此推出所有 Host、真实 LAN/Gateway、浏览器 profile 或用户生产项目均已覆盖。</p><p>本次发布是私有母版 Runtime/Shell，不包含独立 Open Dev Team Edition，也不要求现有 TASK、REPORT、Session 或 Activity 文件做数据迁移。</p><h2 id="可以迁移到其他-agent-runtime-的审查方法" tabindex="-1">可以迁移到其他 Agent Runtime 的审查方法 <a class="header-anchor" href="#可以迁移到其他-agent-runtime-的审查方法" aria-label="Permalink to &quot;可以迁移到其他 Agent Runtime 的审查方法&quot;">​</a></h2><p>如果一个 Agent 系统开始记录 Skill、Tool、Hook 或 MCP 调用，可以逐项检查：</p><ol><li><code>session_id</code> 来自调用方自报，还是 Runtime 权威注册事实？</li><li>Session 是否同时与 task、thread、agent、caller 和状态核对？</li><li>“合法无 Session”和“Session 声明错误”是否被区分？</li><li>错误 claim 是否作为负面审计事实保留，而不是被静默删除或猜测修正？</li><li>身份核验和日志完整性是否被当成两套不同证明？</li><li>task/thread/session 是否各自保持语义，而不是互相替代？</li><li>UI、EVAL 和恢复逻辑是否只把 <code>verified</code> 当作已核验归属？</li><li>调用成功是否仍与工程结果、业务结果的验证分离？</li><li>历史缺失身份是否保持未知，而不是为了“数据完整”而推断补齐？</li></ol><p>这些问题比“日志有没有 Session 字段”更能判断系统是否真正拥有可信执行证据。</p><h2 id="工程结论" tabindex="-1">工程结论 <a class="header-anchor" href="#工程结论" aria-label="Permalink to &quot;工程结论&quot;">​</a></h2><p>CodeFlowMu 这次工程化最重要的变化，不是让技能 journal 多保存了一个 ID。</p><p>而是明确了三种证据等级：</p><p><strong>调用方可以提出身份声明；Runtime 负责核验；只有核验通过的身份才能成为可信执行证据。</strong></p><p>合法无会话必须有自己的语义，错误声明也必须作为负面事实留下。这样，后续恢复、EVAL、审计和治理才能建立在可验证身份上，而不是建立在“某个字段看起来像真的”之上。</p><p>对于数字员工运行体，Session 不是上下文装饰，也不是调用者想写什么就写什么的标签。</p><p>它是回答“这件事到底发生在哪一次真实执行里”的证据边界。</p><h2 id="证据范围与主要来源" tabindex="-1">证据范围与主要来源 <a class="header-anchor" href="#证据范围与主要来源" aria-label="Permalink to &quot;证据范围与主要来源&quot;">​</a></h2><ul><li><a href="/joinwell52/zh/research/evidence/2026-08-28-skill-session-evidence">历史剖面、混合证据样本、V2.1.2 工程更新与公开版本说明</a>：旧 fixture、Reader 与 check 用于验证冻结历史材料的一致性；公开页同时给出脱敏实现、C1 独立 QA、发布门禁与残余风险说明。</li><li><a href="https://github.com/OpenHands/OpenHands/pull/16971" target="_blank" rel="noreferrer">OpenHands PR #16971</a>：原研究于 2026-08-28 记录为开放提案，提供“配置进入会话”的相邻问题模型，不是 CodeFlowMu 本次能力的来源代码或交付证明。</li><li>CodeFlowMu V2.1.2 的实现、独立 QA 与发布原始日志位于受限私有母版中；本文不向公共读者提供不可访问的私有仓库链接。</li><li>本文不证明技能建议正确、不证明 Agent 完整遵循技能、不把调用证据替代工程结果验收，也不声称历史 Session 身份可以被安全推断回填。</li></ul>',120))])}const _=i(l,[["render",r]]);export{S as __pageData,_ as default};
